<?php
defined( 'ABSPATH' ) || exit;
$module = awd_lm_get_landing_module( $key );
if ( ! $module ) { return; }
$localized = static function ( $path, $default = '' ) use ( $content, $lang ) {
	$value = awd_lm_array_get( $content, $path, $default );
	if ( ! is_array( $value ) ) { return $value; }
	return isset( $value[ $lang ] ) && '' !== trim( (string) $value[ $lang ] ) ? $value[ $lang ] : ( $value['de'] ?? $default );
};
$module_copy = array(
	'eyebrow' => $localized( 'hero.eyebrow' ), 'title' => $localized( 'hero.title' ),
	'text' => $localized( 'hero.text' ), 'button_text' => $localized( 'hero.button_text' ),
	'button_url' => $localized( 'hero.button_url', '#contact' ),
);
$page_title = $localized( 'seo.title', $module['name'] );
$page_description = $localized( 'seo.description', '' );
$css_url = awd_lm_landing_css_url( $key );
$script_url = trailingslashit( AWD_LM_URL ) . ltrim( str_replace( wp_normalize_path( AWD_LM_DIR ), '', wp_normalize_path( $module['script'] ) ), '/' );
?>
<!doctype html><html lang="<?php echo esc_attr( $lang ); ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo esc_html( $page_title ); ?></title><meta name="description" content="<?php echo esc_attr( $page_description ); ?>"><meta name="robots" content="<?php echo ! empty( $preview ) ? 'noindex,nofollow' : 'index,follow'; ?>"><link rel="canonical" href="<?php echo esc_url( $canonical ); ?>"><?php wp_site_icon(); ?><?php foreach ( awd_lm_languages() as $code => $label ) : ?><link rel="alternate" hreflang="<?php echo esc_attr( $code ); ?>" href="<?php echo esc_url( awd_lm_public_url( $key, $code ) ); ?>"><?php endforeach; ?><link rel="stylesheet" href="<?php echo esc_url( $css_url ); ?>"><?php if ( awd_lm_turnstile_enabled() ) : ?><script src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit" async defer></script><?php endif; ?><?php if ( ! empty( $editor ) ) : ?><link rel="stylesheet" href="<?php echo esc_url( AWD_LM_URL . 'admin/visual-editor.css?ver=' . $asset_version ); ?>"><?php endif; ?></head><body class="awd-landing--<?php echo esc_attr( $key ); ?><?php echo ! empty( $editor ) ? ' awd-lm-visual awd-lm-module-visual' : ''; ?>">
<?php if ( ! empty( $editor ) ) : ?>
<form id="awd-lm-visual-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="awd_lm_save"><input type="hidden" name="landing" value="<?php echo esc_attr( $key ); ?>"><input type="hidden" name="editor_lang" value="<?php echo esc_attr( $lang ); ?>"><?php wp_nonce_field( 'awd_lm_save_' . $key ); ?>
	<div class="awd-lm-module-fields-shell" hidden><aside class="awd-lm-module-fields" role="dialog" aria-modal="true" aria-label="Page fields"><button type="button" class="awd-lm-module-fields-close" data-awd-module-fields-close aria-label="Close">×</button><h2><?php echo esc_html( $module['name'] ); ?> — Page fields</h2><?php foreach ( $definition['sections'] as $section_key => $section ) : ?><h3><?php echo esc_html( $section['label'] ); ?></h3><?php foreach ( $section['fields'] as $field => $type ) : ?><?php $value = $content[ $section_key ][ $field ][ $lang ] ?? ''; ?><label><?php echo esc_html( ucwords( str_replace( '_', ' ', $field ) ) ); ?><?php if ( in_array( $type, array( 'textarea','lines','faq' ), true ) ) : ?><textarea name="content[<?php echo esc_attr( $section_key ); ?>][<?php echo esc_attr( $field ); ?>][<?php echo esc_attr( $lang ); ?>]" rows="3"><?php echo esc_textarea( $value ); ?></textarea><?php else : ?><input name="content[<?php echo esc_attr( $section_key ); ?>][<?php echo esc_attr( $field ); ?>][<?php echo esc_attr( $lang ); ?>]" value="<?php echo esc_attr( $value ); ?>"><?php endif; ?></label><?php endforeach; ?><?php endforeach; ?><div class="awd-lm-module-fields-actions"><button type="button" data-awd-module-fields-close>Done</button></div></aside></div>
</form>
<div class="awd-lm-toolbar"><div class="awd-lm-toolbar-brand"><a class="awd-lm-back" href="<?php echo esc_url( admin_url() ); ?>">← WordPress</a><span class="awd-lm-toolbar-divider" aria-hidden="true"></span><strong><span class="awd-lm-toolbar-dot" aria-hidden="true"></span>Landing Manager</strong><label class="awd-lm-landing-picker"><span>Landing</span><select data-awd-landing-switcher aria-label="Select landing page"><?php foreach ( awd_lm_definitions() as $landing_key => $landing_definition ) : ?><option value="<?php echo esc_url( add_query_arg( array( 'action'=>'awd_lm_visual_editor','landing'=>$landing_key,'lang'=>$lang ), admin_url( 'admin-post.php' ) ) ); ?>" <?php selected( $key, $landing_key ); ?>><?php echo esc_html( $landing_definition['name'] ); ?></option><?php endforeach; ?></select></label></div><div class="awd-lm-toolbar-actions"><div class="awd-lm-language-tabs" aria-label="Editing language"><?php foreach ( awd_lm_languages() as $code => $label ) : ?><a class="<?php echo $lang === $code ? 'is-current' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'action'=>'awd_lm_visual_editor','landing'=>$key,'lang'=>$code ), admin_url( 'admin-post.php' ) ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?></div><span class="awd-lm-toolbar-divider awd-lm-actions-divider"></span><?php echo awd_lm_admin_navigation( 'website', false ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><a class="awd-lm-preview-link" href="<?php echo esc_url( awd_lm_public_url( $key, $lang ) ); ?>" target="_blank" rel="noopener">View published <span aria-hidden="true">↗</span></a><button type="button" data-awd-module-fields-toggle>Page fields</button><button type="submit" form="awd-lm-visual-form">Save draft</button><button type="submit" form="awd-lm-visual-form" name="awd_publish_after_save" value="1" class="awd-lm-publish-button">Publish all <span>→</span></button></div></div>
<?php endif; ?>
<?php include $module['template']; ?>
<?php if ( empty( $editor ) && empty( $preview ) ) : ?><script src="<?php echo esc_url( AWD_LM_URL . 'assets/analytics.js?ver=' . $asset_version ); ?>" data-enabled="1" data-endpoint="<?php echo esc_url( add_query_arg( 'action', 'awd_lm_track', admin_url( 'admin-post.php' ) ) ); ?>" data-language="<?php echo esc_attr( $lang ); ?>" data-landing="<?php echo esc_attr( $key ); ?>" defer></script><?php endif; ?><script src="<?php echo esc_url( AWD_LM_URL . 'assets/vendor/libphonenumber-max.js?ver=1.13.11' ); ?>" defer></script><?php if ( wp_normalize_path( $module['script'] ) !== wp_normalize_path( AWD_LM_DIR . 'assets/landing-v1.js' ) ) : ?><script src="<?php echo esc_url( AWD_LM_URL . 'assets/landing-v1.js?ver=' . $asset_version ); ?>" defer></script><?php endif; ?><script src="<?php echo esc_url( $script_url ); ?>" defer></script><?php if ( ! empty( $editor ) ) : ?><script src="<?php echo esc_url( AWD_LM_URL . 'admin/visual-editor.js?ver=' . $asset_version ); ?>" defer></script><?php wp_print_footer_scripts(); wp_print_media_templates(); endif; ?></body></html>
